// ─── AI helpers ──────────────────────────────────────────────────────────────

function getGroqKey(): string {
  try {
    const raw = localStorage.getItem('atlantis:promptlab:keys');
    if (!raw) return '';
    return JSON.parse(raw).groq ?? '';
  } catch { return ''; }
}

const AI_SYSTEM_PROMPT = `You are a code generator. The user describes what they want and you return ONLY a JSON object with the code. No explanation, no markdown fences, no extra text — just the raw JSON.

Return format:
{"html": "...", "css": "...", "js": "...", "react": "..."}

Rules:
- html: the body content only (no <html>, <head>, <body> tags)
- css: complete CSS
- js: vanilla JavaScript (runs after HTML)
- react: JSX code using React 18 loaded from a CDN (global React and ReactDOM). Do NOT use import statements. Destructure hooks from the global: const { useState, useEffect, useRef, useMemo, useCallback } = React; Always include the render call: const root = ReactDOM.createRoot(document.getElementById('root')); root.render(<App />); The html field MUST contain <div id="root"></div> when react is used.
- If a field is not needed, set it to ""
- Use real newlines (\\n) in the code strings for readability — do NOT put everything on one line
- Indent with 2 spaces
- Return valid JSON only`;

interface AICodeResult {
  html: string;
  css: string;
  js: string;
  react: string;
}

interface ExistingCode {
  html: string;
  css: string;
  js: string;
  react: string;
}

async function generateCode(groqKey: string, prompt: string, existing?: ExistingCode, signal?: AbortSignal): Promise<AICodeResult> {
  const hasCode = existing && (existing.html || existing.css || existing.js || existing.react);
  const userContent = hasCode
    ? `Here is the current code:\n\`\`\`json\n${JSON.stringify(existing, null, 2)}\n\`\`\`\n\nUser request: ${prompt}\n\nModify the existing code based on the request. Keep what works, change what's asked.`
    : prompt;

  const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${groqKey}`,
    },
    body: JSON.stringify({
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: AI_SYSTEM_PROMPT },
        { role: 'user', content: userContent },
      ],
      stream: false,
      max_tokens: 4000,
      temperature: 0.3,
    }),
    signal,
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Groq ${res.status}: ${text.slice(0, 200)}`);
  }

  const json = await res.json();
  const raw = json.choices?.[0]?.message?.content?.trim() ?? '';

  // Extract JSON from response (handle if model wraps in markdown fences)
  const jsonMatch = raw.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('No valid JSON in response');

  const parsed = JSON.parse(jsonMatch[0]);

  // Simple formatting: ensure code has line breaks
  const fmt = (code: string) => {
    if (!code) return '';
    // If code already has newlines, it's formatted
    if (code.includes('\n')) return code;
    // Basic formatting for single-line code
    return code
      .replace(/;\s*/g, ';\n')
      .replace(/\{\s*/g, '{\n  ')
      .replace(/\}\s*/g, '\n}\n')
      .replace(/,\s*\n\s*\n/g, ',\n')
      .trim();
  };

  return {
    html: fmt(parsed.html ?? ''),
    css: fmt(parsed.css ?? ''),
    js: fmt(parsed.js ?? ''),
    react: fmt(parsed.react ?? ''),
  };
}

