// ─── Helpers ─────────────────────────────────────────────────────────────────

function buildSrcdoc(html: string, css: string, js: string, compiledTs = '', compiledReact = ''): string {
  const reactCdn = compiledReact ? `
<script src="https://unpkg.com/react@18/umd/react.development.js"></script>
<script src="https://unpkg.com/react-dom@18/umd/react-dom.development.js"></script>` : '';
  return `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>*, *::before, *::after { box-sizing: border-box; }
${css}
</style>
${reactCdn}
</head>
<body>
${html}
<script>
(function() {
  const send = (kind, args) => {
    window.parent.postMessage({ type: 'console', kind, text: args.map(a => {
      try { return typeof a === 'object' ? JSON.stringify(a) : String(a); } catch { return String(a); }
    }).join(' ') }, '*');
  };
  ['log','warn','error'].forEach(m => {
    const orig = console[m].bind(console);
    console[m] = (...args) => { orig(...args); send(m, args); };
  });
  window.addEventListener('error', e => send('error', [e.message + ' (' + e.filename + ':' + e.lineno + ')']));
})();
</script>
<script>${js}</script>
${compiledTs ? `<script>${compiledTs}</script>` : ''}
${compiledReact ? `<script>${compiledReact}</script>` : ''}
</body>
</html>`;
}

interface ConsoleMsg { kind: 'log' | 'error' | 'warn'; text: string; id: number; }
type Lang = 'html' | 'css' | 'js' | 'ts' | 'react';

// ─── Component ───────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const initial = EXAMPLES[0];
  const [html, setHtml] = useState(initial.html);
  const [css, setCss] = useState(initial.css);
  const [js, setJs] = useState(initial.js);
  const [ts, setTs] = useState(initial.ts ?? '');
  const [react, setReact] = useState(initial.react ?? '');
  const [activeTab, setActiveTab] = useState<Lang>('html');
  const [srcdoc, setSrcdoc] = useState(() => buildSrcdoc(initial.html, initial.css, initial.js));
  const [editorCollapsed, setEditorCollapsed] = useState(false);
  const [previewCollapsed, setPreviewCollapsed] = useState(false);
  const [consoleMsgs, setConsoleMsgs] = useState<ConsoleMsg[]>([]);
  const [menuOpen, setMenuOpen] = useState(false);
  const [saveOpen, setSaveOpen] = useState(false);
  const [currentDoc, setCurrentDoc] = useState<{ id: string; name: string } | null>(null);
  const menuRef = useRef<HTMLDivElement>(null);
  const msgId = useRef(0);

  // AI generation
  const [aiPrompt, setAiPrompt] = useState('');
  const [aiGenerating, setAiGenerating] = useState(false);
  const [aiError, setAiError] = useState('');
  const groqKey = getGroqKey();
  const hasAI = Boolean(groqKey);


  const handleSave = async (name: string) => {
    setSaveOpen(false);
    await saveDoc('playground', name, JSON.stringify({ html, css, js, ts, react }));
    setCurrentDoc(null);
  };

  const handleUpdate = async () => {
    if (!currentDoc) return;
    setSaveOpen(false);
    await updateDoc(currentDoc.id, currentDoc.name, JSON.stringify({ html, css, js, ts, react }));
  };

  const handleLoad = (content: string, docId?: string, docName?: string) => {
    setCurrentDoc(docId && docName ? { id: docId, name: docName } : null);
    try {
      const { html: h, css: c, js: j, ts: t, react: r } = JSON.parse(content);
      setHtml(h ?? ''); setCss(c ?? ''); setJs(j ?? ''); setTs(t ?? ''); setReact(r ?? '');
      setSrcdoc(buildSrcdoc(h ?? '', c ?? '', j ?? ''));
      setConsoleMsgs([]);
    } catch { /* ignore malformed saves */ }
  };

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) setMenuOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  useEffect(() => {
    const handler = (e: MessageEvent) => {
      if (e.data?.type === 'console') {
        setConsoleMsgs((prev) => [
          ...prev.slice(-49),
          { kind: e.data.kind, text: e.data.text, id: msgId.current++ },
        ]);
      }
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, []);

  const runWith = useCallback(async (h: string, c: string, j: string, t: string, r: string) => {
    setConsoleMsgs([]);
    const needsBabel = t.trim() || r.trim();
    const Babel = needsBabel ? await import('@babel/standalone') : null;

    let compiledTs = '';
    if (t.trim() && Babel) {
      try {
        const result = Babel.transform(t, {
          presets: [['typescript', { allExtensions: true }]],
          filename: 'script.ts',
        });
        compiledTs = result?.code ?? '';
      } catch (e: any) {
        setConsoleMsgs([{ kind: 'error', text: `TypeScript: ${e.message}`, id: msgId.current++ }]);
        return;
      }
    }

    let compiledReact = '';
    if (r.trim() && Babel) {
      try {
        const result = Babel.transform(r, {
          presets: [
            ['typescript', { allExtensions: true, isTSX: true }],
            ['react', { runtime: 'classic' }],
          ],
          filename: 'component.tsx',
        });
        compiledReact = result?.code ?? '';
      } catch (e: any) {
        setConsoleMsgs([{ kind: 'error', text: `React: ${e.message}`, id: msgId.current++ }]);
        return;
      }
    }

    setSrcdoc(buildSrcdoc(h, c, j, compiledTs, compiledReact));
  }, []);

  const handleAIGenerate = useCallback(async () => {
    if (!groqKey || !aiPrompt.trim() || aiGenerating) return;
    setAiGenerating(true);
    setAiError('');
    try {
      const result = await generateCode(groqKey, aiPrompt, { html, css, js, react });
      setHtml(result.html);
      setCss(result.css);
      setJs(result.js);
      setReact(result.react);
      setTs('');
      setConsoleMsgs([]);
      setAiPrompt('');
      if (result.react) {
        setActiveTab('react');
        runWith(result.html, result.css, result.js, '', result.react);
      } else {
        setActiveTab('html');
        runWith(result.html, result.css, result.js, '', '');
      }
    } catch (err: unknown) {
      setAiError(err instanceof Error ? err.message : String(err));
    } finally {
      setAiGenerating(false);
    }
  }, [groqKey, aiPrompt, aiGenerating, runWith, html, css, js, react]);

  const run = useCallback(
    () => runWith(html, css, js, ts, react),
    [html, css, js, ts, react, runWith]
  );

  const loadExample = (ex: typeof EXAMPLES[0]) => {
    const h = ex.html, c = ex.css, j = ex.js, t = ex.ts ?? '', r = ex.react ?? '';
    setHtml(h); setCss(c); setJs(j); setTs(t); setReact(r);
    setConsoleMsgs([]);
    // Auto-run immediately with example values (don't wait for state to settle)
    runWith(h, c, j, t, r);
    if (r) setActiveTab('react');
    else if (t) setActiveTab('ts');
    else setActiveTab('html');
    setMenuOpen(false);
  };

  const handleCollapseEditor = () => {
    if (!editorCollapsed && previewCollapsed) setPreviewCollapsed(false);
    setEditorCollapsed((c) => !c);
  };

  const handleCollapsePreview = () => {
    if (!previewCollapsed && editorCollapsed) setEditorCollapsed(false);
    setPreviewCollapsed((c) => !c);
  };

  const currentValue = activeTab === 'html' ? html : activeTab === 'css' ? css : activeTab === 'js' ? js : activeTab === 'ts' ? ts : react;
  const currentSetter = activeTab === 'html' ? setHtml : activeTab === 'css' ? setCss : activeTab === 'js' ? setJs : activeTab === 'ts' ? setTs : setReact;

  const topBarControls = (
    <div style={{ display: 'flex', alignItems: 'center', gap: theme.spacing.sm }}>
      <ToolBtn onClick={() => { setHtml(''); setCss(''); setJs(''); setTs(''); setReact(''); setConsoleMsgs([]); setSrcdoc(buildSrcdoc('','','')); }} title="Clear all panels">
        New
      </ToolBtn>
      <DocumentsMenu appId="playground" onLoad={handleLoad} />
      <SaveBtn onClick={() => setSaveOpen(true)}><Save size={13} /> Save</SaveBtn>
      <RunBtn onClick={run}>
        <Play size={13} /> Run
      </RunBtn>
      <IconBtn onClick={() => setConsoleMsgs([])} title="Clear console">
        <RefreshCw size={13} />
      </IconBtn>
      <DropdownWrapper ref={menuRef}>
        <ToolBtn onClick={() => setMenuOpen((o) => !o)}>
          Examples <ChevronDown size={12} />
        </ToolBtn>
        {menuOpen && (
          <DropdownMenu>
            {EXAMPLES.map((ex) => (
              <DropdownItem key={ex.label} onClick={() => loadExample(ex)}>
                {ex.label}
              </DropdownItem>
            ))}
          </DropdownMenu>
        )}
      </DropdownWrapper>
      {topBarRight}
    </div>
  );

  return (
    <Layout title="Playground" sidebar={<DevToolkitNav activeAppId="playground" />} topBarRight={topBarControls}>
      {saveOpen && <SaveDialog onSave={handleSave} onUpdate={handleUpdate} existingDoc={currentDoc ?? undefined} onCancel={() => setSaveOpen(false)} />}

      {hasAI && (
        <AIBar>
          <Sparkles size={14} style={{ color: theme.colors.accent, flexShrink: 0 }} />
          <AIInput
            placeholder="Describe what you want to build…"
            value={aiPrompt}
            onChange={(e) => setAiPrompt(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter' && !aiGenerating) handleAIGenerate(); }}
          />
          {aiError && <AIError title={aiError}>{aiError}</AIError>}
          <AIBtn disabled={aiGenerating || !aiPrompt.trim()} onClick={handleAIGenerate}>
            {aiGenerating ? <SpinIcon size={14} /> : <Sparkles size={14} />}
            {aiGenerating ? 'Generating…' : 'Generate'}
          </AIBtn>
        </AIBar>
      )}

      <Body>
        {/* ── Left: editors ── */}
        {editorCollapsed ? (
          <div style={{ position: 'relative', flexShrink: 0 }}>
            <CollapsedTab onClick={handleCollapseEditor} title="Show editors">
              <PanelLeftOpen size={14} />
              <VerticalLabel>Editor</VerticalLabel>
            </CollapsedTab>
          </div>
        ) : (
          <EditorsPaneWrapper collapsed={false}>
            <PaneHeader>
              {(['html', 'css', 'js', 'ts', 'react'] as Lang[]).map((lang) => (
                <Tab
                  key={lang}
                  lang={lang}
                  active={activeTab === lang}
                  onClick={() => setActiveTab(lang)}
                >
                  <LangDot lang={lang} />
                  {lang === 'react' ? 'React' : lang.toUpperCase()}
                </Tab>
              ))}
              <CollapseBtn onClick={handleCollapseEditor} title="Collapse editors">
                <PanelLeftClose size={14} />
              </CollapseBtn>
            </PaneHeader>
            <CodeEditor
              key={activeTab}
              lang={activeTab}
              value={currentValue}
              onChange={currentSetter}
            />
          </EditorsPaneWrapper>
        )}

        {/* ── Right: preview ── */}
        {previewCollapsed ? (
          <div style={{ position: 'relative', flexShrink: 0 }}>
            <PreviewCollapsedTab onClick={handleCollapsePreview} title="Show preview">
              <PanelRightOpen size={14} />
              <VerticalLabel>Preview</VerticalLabel>
            </PreviewCollapsedTab>
          </div>
        ) : (
          <PreviewPaneWrapper collapsed={false}>
            <PreviewHeader>
              <PreviewTitle>Preview</PreviewTitle>
              <CollapseBtn onClick={handleCollapsePreview} title="Collapse preview">
                <PanelRightClose size={14} />
              </CollapseBtn>
            </PreviewHeader>
            <PreviewContent>
              <PreviewFrame
                key={srcdoc}
                srcDoc={srcdoc}
                sandbox="allow-scripts"
                title="preview"
              />
            </PreviewContent>
            {consoleMsgs.length > 0 && (
              <ConsoleBar>
                {consoleMsgs.map((m) => (
                  <ConsoleEntry key={m.id} kind={m.kind}>
                    [{m.kind}] {m.text}
                  </ConsoleEntry>
                ))}
              </ConsoleBar>
            )}
          </PreviewPaneWrapper>
        )}
      </Body>
    </Layout>
  );
}
